param([Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
function Failure-Of($ErrorRecord){$e=$ErrorRecord.Exception;while($e.InnerException){$e=$e.InnerException};$r=[ordered]@{ok=$false;exception=$e.GetType().FullName;message=$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})};if($e -is [Text.EncoderFallbackException]){$r.unknown=[int]$e.CharUnknown;$r.index=$e.Index;$r.high=[int]$e.CharUnknownHigh;$r.low=[int]$e.CharUnknownLow;$r.isPair=$e.IsUnknownSurrogate()};if($e -is [Text.DecoderFallbackException]){$r.bytesUnknown=[int[]]$e.BytesUnknown;$r.index=$e.Index};return $r}

$replacements=@(@(),@(0),@(65,0),@(0,66),@(65,0,66),@(55296,56320),@(65,0,55296,56320),@(55296,56320,0,65),@(0,55296,56320,0));$profiles=[Collections.Generic.List[object]]::new();$calls=0
foreach($bigEndian in @($false,$true)){foreach($replacement in $replacements){$text=[string]::new([char[]][int[]]$replacement);$owner=[Text.Encoding]([Text.UnicodeEncoding]::new($bigEndian,$true,$false)).Clone();$owner.EncoderFallback=[Text.EncoderReplacementFallback]::new($text);$owner.DecoderFallback=[Text.DecoderReplacementFallback]::new($text);$m=[Math]::Max(1,$replacement.Count);$rows=[Collections.Generic.List[object]]::new()
 foreach($method in @('GetMaxByteCount','GetMaxCharCount')){$bound=if($method -eq 'GetMaxByteCount'){[long][Math]::Floor([int]::MaxValue/(2.0*$m))-1}else{2*([long][Math]::Floor([int]::MaxValue/[double]$m)-1)};$inputs=[Collections.Generic.SortedSet[int]]::new();foreach($n in @(-2147483648,-1,0,1,2,3,4,7,8,15,16,31,32,255,256,65535,65536,1073741822,1073741823,1073741824,2147483646,2147483647)){[void]$inputs.Add([int]$n)};foreach($delta in -3..3){$n=$bound+$delta;if($n -ge 0 -and $n -le [int]::MaxValue){[void]$inputs.Add([int]$n)}}
  foreach($n in $inputs){try{$value=if($method -eq 'GetMaxByteCount'){$owner.GetMaxByteCount($n)}else{$owner.GetMaxCharCount($n)};$result=[ordered]@{ok=$true;count=$value}}catch{$result=Failure-Of $_};$rows.Add([ordered]@{method=$method;input=$n;result=$result});$calls++}
 };$profiles.Add([ordered]@{bigEndian=$bigEndian;replacement=[int[]]$replacement;encoderMaxCharCount=$owner.EncoderFallback.MaxCharCount;decoderMaxCharCount=$owner.DecoderFallback.MaxCharCount;rows=$rows.ToArray()})
}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();nativeCalls=$calls;profiles=$profiles.ToArray();qualification='NATIVE_SELECTED_UTF16_REPLACEMENT_MAXIMUM_COUNT_BOUNDARIES_ONLY; NO_FULL_PARITY_OR_TASK_ACCEPTANCE'};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 12 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS UTF16 replacement max count capture: $calls calls"
